<script setup>
import { onMounted, onBeforeUnmount, reactive, ref } from 'vue'
import AppHeader from '@/components/AppHeader.vue'
import UiButton from '@/components/UiButton.vue'
import UiModal from '@/components/UiModal.vue'
import { http } from '@/api/http'
import { unwrapResult } from '@/utils/result'
import { getMerchantProducts, listMerchants } from '@/api/merchant'
import { useAuthStore } from '@/stores/auth'

const auth = useAuthStore(), root = '/platform/operations/v2'
const names = { TRACKING: '物流轨迹', WAYBILL: '电子面单', LOCAL_DELIVERY: '同城配送', ALERT: '站外告警', OFFSITE_BACKUP: '异地备份', MINIAPP_RELEASE: '批量小程序发布' }
const rows = ref([]), tasks = ref([]), merchants = ref([]), apps = ref([]), selectedStore = ref(''), selectedApps = ref([]), error = ref(''), result = ref(null), loading = ref(false), busy = ref(false), editor = ref(null), pending = ref(null)
const form = reactive({}), release = reactive({ versionName: '', artifactSha256: '' }), authorization = reactive({ applicationId: '', authorized: false, evidence: '' })
const key = `platform-integrations:${auth.user?.id || 'admin'}`
let disposed = false
try { pending.value = JSON.parse(localStorage.getItem(key) || 'null') } catch { pending.value = { damaged: true }; error.value = '原模拟任务恢复记录损坏，请先核对任务记录' }
const requestId = () => `platform-${Date.now()}-${Math.random().toString(36).slice(2)}`
async function get(path) { return unwrapResult(await http.get(root + path)) }
async function load() { loading.value = true; error.value = ''; const values = await Promise.allSettled([get('/integrations'), get('/tasks'), listMerchants({ page: 1, pageSize: 100 })]); if (disposed) return; if (values[0].status === 'fulfilled') rows.value = values[0].value.list; if (values[1].status === 'fulfilled') tasks.value = values[1].value.list.map(row => ({ ...row, result: typeof row.resultPayload === 'string' ? JSON.parse(row.resultPayload) : row.resultPayload })); if (values[2].status === 'fulfilled') merchants.value = values[2].value.list || values[2].value.records || []; error.value = values.filter(v => v.status === 'rejected').map(v => v.reason.message).join('；'); loading.value = false }
function open(row) { if (busy.value || pending.value) return; Object.keys(form).forEach(key => delete form[key]); Object.assign(form, { ...row, accountId: '', secret: '', endpoint: '', bucket: '', region: '' }); editor.value = row }
async function save() { if (busy.value || pending.value) return; busy.value = true; error.value = ''; try { const credentials = Object.fromEntries(['accountId', 'secret', 'endpoint', 'bucket', 'region'].filter(key => form[key].trim()).map(key => [key, form[key].trim()])); await http.put(`${root}/integrations/${form.kind}`, { expectedVersion: form.version, mode: form.mode, provider: form.provider, credentials }).then(unwrapResult); editor.value = null; await load() } catch (e) { error.value = e.message + '。请刷新读取最新状态再修改'; editor.value = null } finally { busy.value = false; form.secret = '' } }
async function submit(path, body = {}) { if (busy.value || pending.value) return; const value = { path, body: { ...body, requestKey: requestId() } }; try { localStorage.setItem(key, JSON.stringify(value)); pending.value = value } catch { error.value = '无法保存任务恢复记录，暂不能提交'; return } return retry() }
async function retry() { if (busy.value || !pending.value || pending.value.damaged) return; const operation = pending.value; if (!/^\/(integrations\/(TRACKING|WAYBILL|LOCAL_DELIVERY|ALERT|OFFSITE_BACKUP|MINIAPP_RELEASE)\/simulate|applications\/\d+\/authorization)$/.test(operation.path) || !operation.body?.requestKey) { error.value = '原任务格式无效，请先核对任务记录'; return } busy.value = true; error.value = ''; try { result.value = unwrapResult(await http.post(root + operation.path, operation.body)); localStorage.removeItem(key); pending.value = null; await load() } catch (e) { error.value = e.message; if ([400, 409, 422].includes(e.code) || [400, 409, 422].includes(e.response?.status)) { localStorage.removeItem(key); pending.value = null } } finally { busy.value = false } }
async function loadApps() { apps.value = []; selectedApps.value = []; if (!selectedStore.value) return; try { const result = await getMerchantProducts(selectedStore.value); apps.value = (result.products || result.list || []).map(p => p.application).filter(Boolean) } catch (e) { error.value = e.message } }
function publishMock() { if (!selectedApps.value.length || !release.versionName.trim() || !/^[a-f0-9]{64}$/.test(release.artifactSha256)) { error.value = '请选择已授权应用、填写版本名称和发布包校验值'; return } submit('/integrations/MINIAPP_RELEASE/simulate', { ...release, applicationIds: selectedApps.value.map(Number), reference: '批量发布模拟验收' }) }
onMounted(load); onBeforeUnmount(() => { disposed = true })
</script>

<template>
  <div class="min-h-screen bg-[#F5F7FA]">
    <AppHeader /><main class="mx-auto max-w-[1280px] px-4 py-6 sm:px-6">
      <header class="mb-6 flex flex-wrap items-start justify-between gap-4"><div><h1 class="text-2xl font-semibold text-slate-900">接入与发布</h1><p class="mt-2 text-sm text-slate-500">管理外部服务配置、模拟验收和小程序发布准备。</p></div><UiButton variant="secondary" :disabled="busy || loading" @click="load">刷新</UiButton></header>
      <div class="mb-5 rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm leading-7 text-amber-900">当前仅支持配置和模拟。模拟不会发出外部请求，不会发送站外消息、上传异地文件或向微信提交发布。实际备份和恢复记录仍在“运行保障”查看。</div>
      <div v-if="error" role="alert" class="mb-5 rounded-lg bg-red-50 p-4 text-sm text-red-700">{{ error }}</div><div v-if="pending" class="mb-5 rounded-lg border border-amber-300 bg-white p-4 text-sm"><p>有一项任务结果待确认，恢复时沿用原请求。</p><UiButton class="mt-3" :disabled="busy || pending.damaged" @click="retry">重试原任务</UiButton></div>
      <div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><article v-for="row in rows" :key="row.kind" class="rounded-xl border border-slate-200 bg-white p-5"><div class="flex items-center justify-between gap-3"><h2 class="font-semibold text-slate-900">{{ names[row.kind] }}</h2><span class="rounded-full bg-slate-100 px-3 py-1 text-xs text-slate-600">{{ row.mode === 'MOCK' ? '模拟模式' : '未启用' }}</span></div><p class="mt-3 text-sm text-slate-500">配置版本 {{ row.version }} · 真实调用未启用</p><p v-if="row.kind === 'ALERT'" class="mt-2 text-xs leading-6 text-slate-500">开启模拟后，会从已捕捉的接口异常生成去重告警任务，实际未对外发送。</p><p v-if="row.kind === 'OFFSITE_BACKUP'" class="mt-2 text-xs leading-6 text-slate-500">模拟上传、校验与恢复步骤；不代表已有可用的异地备份。</p><div class="mt-5 flex flex-wrap gap-2"><UiButton variant="secondary" :disabled="busy || !!pending" @click="open(row)">配置</UiButton><UiButton v-if="row.kind !== 'MINIAPP_RELEASE'" :disabled="busy || !!pending || row.mode !== 'MOCK'" @click="submit(`/integrations/${row.kind}/simulate`, { reference: '人工模拟验收' })">模拟验收</UiButton></div></article></div>
      <section class="mt-6 rounded-xl border border-slate-200 bg-white p-5 sm:p-6"><h2 class="font-semibold text-slate-900">小程序授权记录与批量发布模拟</h2><p class="mt-2 text-sm leading-7 text-slate-500">先登记商家授权凭证，再选择应用运行模拟。授权记录仅供准备工作使用，微信平台授权尚未验证。</p><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="field">选择门店<select v-model="selectedStore" @change="loadApps"><option value="">请选择门店（最近100家）</option><option v-for="merchant in merchants" :key="merchant.id" :value="merchant.id">{{ merchant.name }} #{{ merchant.id }}</option></select></label><label class="field">版本名称<input v-model="release.versionName" maxlength="40" placeholder="例如 2.0.0" /></label></div><div class="my-4 grid gap-3 sm:grid-cols-2"><label v-for="app in apps" :key="app.id" class="flex items-center gap-3 rounded-lg border p-3 text-sm"><input v-model="selectedApps" type="checkbox" :value="app.id" />{{ app.productType === 'MALL' ? '商城' : '点餐' }} · 应用 #{{ app.id }}<button class="ml-auto text-blue-700" @click="authorization.applicationId = app.id">登记授权</button></label><p v-if="selectedStore && !apps.length" class="text-sm text-slate-500">未找到应用，请先在门店管理开通产品。</p></div><form v-if="authorization.applicationId" class="mb-5 rounded-lg bg-slate-50 p-4" @submit.prevent="submit(`/applications/${authorization.applicationId}/authorization`, authorization)"><p class="text-sm font-medium">应用 #{{ authorization.applicationId }} 授权记录</p><label class="field mt-3">授权凭证说明（合同／文件编号）<input v-model="authorization.evidence" maxlength="255" required /></label><label class="my-3 flex items-center gap-2 text-sm"><input v-model="authorization.authorized" type="checkbox" />已取得该商家授权（取消勾选表示撤销登记）</label><UiButton type="submit" :disabled="busy || !!pending">保存授权记录</UiButton></form><label class="field">发布包SHA-256校验值<input v-model="release.artifactSha256" maxlength="64" placeholder="发布包的64位校验值" class="font-mono" /></label><UiButton class="mt-4" :disabled="busy || !!pending || !selectedApps.length || rows.find(r => r.kind === 'MINIAPP_RELEASE')?.mode !== 'MOCK'" @click="publishMock">模拟发布所选应用</UiButton></section>
      <section v-if="result" class="mt-6 rounded-xl border bg-emerald-50 p-5 text-sm" aria-live="polite"><h2 class="font-semibold">最近操作结果</h2><p class="mt-2">{{ result.mode === 'MOCK' ? '模拟完成，实际对外请求为0次。' : '授权记录已保存；微信授权状态未验证。' }}</p><p v-if="result.trackingNo" class="mt-2">模拟单号：{{ result.trackingNo }}</p><p v-if="result.note" class="mt-2">{{ result.note }}</p></section>
      <section class="mt-6 rounded-xl border bg-white p-5"><h2 class="font-semibold text-slate-900">最近任务</h2><div class="mt-4 overflow-x-auto"><table class="w-full min-w-[650px] text-left text-sm"><thead class="border-b text-slate-500"><tr><th class="p-3">任务</th><th class="p-3">范围</th><th class="p-3">结果</th><th class="p-3">实际执行</th><th class="p-3">时间</th></tr></thead><tbody><tr v-for="task in tasks" :key="task.id" class="border-b"><td class="p-3">{{ names[task.kind] || (task.kind === 'RELEASE_AUTH' ? '授权记录' : task.kind) }} #{{ task.id }}</td><td class="p-3">{{ task.scopeId === 0 ? '平台' : '#' + task.scopeId }}</td><td class="p-3">{{ task.status === 'SIMULATED' ? '模拟完成' : '已记录' }}</td><td class="p-3">{{ task.kind === 'RELEASE_AUTH' ? '未验证微信授权' : '未对外执行' }}</td><td class="p-3">{{ task.createdAt?.replace('T', ' ') }}</td></tr></tbody></table></div><p class="mt-3 text-xs text-slate-500">显示最近100条任务。</p></section>
      <UiModal :open="!!editor" :title="'配置' + (names[form.kind] || '')" @close="!busy && (editor = null)"><form class="space-y-4" @submit.prevent="save"><label class="field">运行方式<select v-model="form.mode" :disabled="busy"><option value="DISABLED">未启用</option><option value="MOCK">模拟模式</option></select></label><label class="field">提供方标识<input v-model="form.provider" maxlength="40" pattern="[A-Z0-9_]{1,40}" placeholder="大写英文，暂未选定可保留 PENDING" :disabled="busy" required /></label><p class="text-xs leading-6 text-slate-500">以下参数均可留空。保存时加密，保存后不回显；空白保留原值。</p><label class="field">账号标识<input v-model="form.accountId" maxlength="1000" autocomplete="off" /></label><label class="field">密钥<input v-model="form.secret" type="password" maxlength="1000" autocomplete="new-password" /></label><label class="field">服务地址<input v-model="form.endpoint" maxlength="1000" autocomplete="off" /></label><div v-if="form.kind === 'OFFSITE_BACKUP'" class="grid gap-4 sm:grid-cols-2"><label class="field">存储桶<input v-model="form.bucket" maxlength="1000" /></label><label class="field">区域<input v-model="form.region" maxlength="1000" /></label></div><p class="text-xs text-amber-700">保存配置不会启用真实服务。</p><UiButton type="submit" :disabled="busy || !!pending">保存配置</UiButton></form></UiModal>
    </main>
  </div>
</template>
<style scoped>
.field{display:flex;flex-direction:column;gap:8px;font-size:13px;color:#475569}.field input,.field select{border:1px solid #cbd5e1;border-radius:7px;background:white;padding:10px 12px;color:#0f172a;width:100%;min-width:0}.field input:focus,.field select:focus{outline:2px solid #bfdbfe;outline-offset:1px}
</style>
